screenPanels.initJs:
function(container, apiUrl, tables) {
  // フォーム要素の取得
  const orderNumberInput = container.querySelector('#order-number');
  const orderDateInput = container.querySelector('#order-date');
  const deliveryDateInput = container.querySelector('#delivery-date');
  const customerSelect = container.querySelector('#customer-select');
  const productCodeInput = container.querySelector('#product-code');
  const productNameInput = container.querySelector('#product-name');
  const quantityInput = container.querySelector('#quantity');
  const unitPriceInput = container.querySelector('#unit-price');
  const totalAmountInput = container.querySelector('#total-amount');
  const deliveryAddressInput = container.querySelector('#delivery-address');
  const notesInput = container.querySelector('#notes');
  const saveBtn = container.querySelector('#btn-save');
  const cancelBtn = container.querySelector('#btn-cancel');

  // 現在の編集対象ID
  let currentEditId = null;

  // 合計金額の自動計算
  function updateTotalAmount() {
    const quantity = parseInt(quantityInput.value) || 0;
    const unitPrice = parseInt(unitPriceInput.value) || 0;
    const total = quantity * unitPrice;
    totalAmountInput.value = total.toLocaleString();
  }

  // 商品コード変更時の商品名自動設定
  function updateProductName() {
    const productCode = productCodeInput.value;
    const productMap = {
      'PRD001': '標準部品A',
      'PRD002': '特殊部品B',
      'PRD003': '消耗品C',
      'PRD004': '工具セットD'
    };
    productNameInput.value = productMap[productCode] || '';
  }

  // 単価交渉履歴の描画
  function renderNegotiationHistory(records) {
    const tbody = container.querySelector('#negotiation-tbody');
    if (!records || records.length === 0) {
      tbody.innerHTML = '<tr><td colspan="4" style="padding: 12px; text-align: center; color: var(--text-muted);">データがありません</td></tr>';
      return;
    }

    tbody.innerHTML = records.slice(0, 5).map(record => {
      const statusColor = record.交渉ステータス === '合意' ? '#22c562' : 
                         record.交渉ステータス === '交渉中' ? '#f59e0b' : '#ef4444';
      return `
        <tr>
          <td style="padding: 6px 8px; color: var(--text);">${record.交渉日?.slice(0, 10) || ''}</td>
          <td style="padding: 6px 8px; color: var(--text);">¥${(record.提案単価 || 0).toLocaleString()}</td>
          <td style="padding: 6px 8px; color: var(--text);">¥${(record.合意単価 || 0).toLocaleString()}</td>
          <td style="padding: 6px 8px; color: var(--text);">
            <span style="background: ${statusColor}20; color: ${statusColor}; padding: 2px 6px; border-radius: 3px; font-size: 11px;">
              ${record.交渉ステータス || ''}
            </span>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 市場価格データの描画
  function renderMarketPrice(records) {
    const tbody = container.querySelector('#market-price-tbody');
    if (!records || records.length === 0) {
      tbody.innerHTML = '<tr><td colspan="4" style="padding: 12px; text-align: center; color: var(--text-muted);">データがありません</td></tr>';
      return;
    }

    tbody.innerHTML = records.slice(0, 5).map(record => `
      <tr>
        <td style="padding: 6px 8px; color: var(--text);">${record.商品名 || ''}</td>
        <td style="padding: 6px 8px; color: var(--text);">¥${(record.市場価格 || 0).toLocaleString()}</td>
        <td style="padding: 6px 8px; color: var(--text);">${record.価格取得日?.slice(0, 10) || ''}</td>
        <td style="padding: 6px 8px; color: var(--text);">${record.価格情報源 || ''}</td>
      </tr>
    `).join('');
  }

  // フォームのクリア
  function clearForm() {
    orderNumberInput.value = '';
    orderDateInput.value = '';
    deliveryDateInput.value = '';
    customerSelect.value = '';
    productCodeInput.value = '';
    productNameInput.value = '';
    quantityInput.value = '1';
    unitPriceInput.value = '';
    totalAmountInput.value = '';
    deliveryAddressInput.value = '';
    notesInput.value = '';
    currentEditId = null;
  }

  // 初期データの読み込み
  async function loadInitialData() {
    try {
      // 単価交渉履歴の読み込み
      const negotiationHistory = await window.aivicApi.list(0);
      renderNegotiationHistory(negotiationHistory);

      // 市場価格データの読み込み
      const marketPriceData = await window.aivicApi.list(1);
      renderMarketPrice(marketPriceData);
    } catch (error) {
      console.error('初期データの読み込みに失敗しました:', error);
    }
  }

  // イベントリスナーの設定
  quantityInput.addEventListener('input', updateTotalAmount);
  unitPriceInput.addEventListener('input', updateTotalAmount);
  productCodeInput.addEventListener('input', updateProductName);

  // 保存ボタンのクリック
  saveBtn.addEventListener('click', async () => {
    try {
      const orderData = {
        発注番号: orderNumberInput.value,
        発注日: orderDateInput.value,
        納期: deliveryDateInput.value,
        顧客ID: customerSelect.value,
        商品コード: productCodeInput.value,
        商品名: productNameInput.value,
        数量: parseInt(quantityInput.value) || 0,
        単価: parseInt(unitPriceInput.value) || 0,
        合計金額: parseInt(unitPriceInput.value || 0) * parseInt(quantityInput.value || 0),
        配送先住所: deliveryAddressInput.value,
        備考: notesInput.value,
        作成日時: new Date().toISOString(),
        更新日時: new Date().toISOString()
      };

      let result;
      if (currentEditId) {
        result = await window.aivicApi.update(0, currentEditId, orderData);
      } else {
        result = await window.aivicApi.save(0, orderData);
      }

      if (result) {
        alert(currentEditId ? '発注データを更新しました' : '発注データを登録しました');
        clearForm();
      }
    } catch (error) {
      console.error('保存に失敗しました:', error);
      alert('保存に失敗しました');
    }
  });

  // キャンセルボタンのクリック
  cancelBtn.addEventListener('click', () => {
    clearForm();
  });

  // 初期化
  loadInitialData();

  // 今日の日付を発注日にセット
  const today = new Date().toISOString().split('T')[0];
  orderDateInput.value = today;
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector('#negotiation-tbody');
  const detailContent = container.querySelector('#detail-content');
  const priceChart = container.querySelector('#price-chart');
  const ctx = priceChart.getContext('2d');
  let selectedNegotiationId = null;

  // 1. テーブル再描画関数
  function renderRows(rows) {
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}" class="cursor-pointer hover:bg-opacity-50" style="background: var(--bg-main);">
        <td class="text-xs">${r.交渉日 ? new Date(r.交渉日).toLocaleDateString('ja-JP') : ''}</td>
        <td class="text-xs">${r.顧客名 || ''}</td>
        <td class="text-xs">${r.商品名 || ''}</td>
        <td class="text-xs">${r.現在単価 ? r.現在単価.toLocaleString() + '円' : ''}</td>
        <td class="text-xs">${r.提案単価 ? r.提案単価.toLocaleString() + '円' : ''}</td>
        <td class="text-xs">${r.合意単価 ? r.合意単価.toLocaleString() + '円' : ''}</td>
        <td class="text-xs">
          <span class="px-2 py-1 rounded text-xs" style="background: ${getStatusColor(r.交渉ステータス)}; color: #fff;">
            ${r.交渉ステータス || ''}
          </span>
        </td>
        <td class="text-xs">${r.営業担当者名 || ''}</td>
        <td class="text-xs">
          <button class="action-btn secondary edit-btn text-xs" data-id="${r.id}">編集</button>
          <button class="action-btn secondary delete-btn text-xs" data-id="${r.id}">削除</button>
        </td>
      </tr>
    `).join('');
    updateSuccessRate(rows);
  }

  function getStatusColor(status) {
    switch(status) {
      case '合意': return '#22c55e';
      case '交渉中': return '#3b82f6';
      case '決裂': return '#ef4444';
      case '保留': return '#f59e0b';
      default: return '#6b7280';
    }
  }

  // 成功率更新
  function updateSuccessRate(rows) {
    const total = rows.length;
    const success = rows.filter(r => r.交渉ステータス === '合意').length;
    const rate = total > 0 ? Math.round((success / total) * 100) : 0;

    container.querySelector('#success-rate').textContent = rate + '%';
    container.querySelector('#total-negotiations').textContent = total + '件';
  }

  // 詳細表示
  function showDetail(negotiation) {
    selectedNegotiationId = negotiation.id;
    detailContent.innerHTML = `
      <div class="space-y-3">
        <div>
          <div class="text-xs" style="color: var(--text-muted);">顧客名</div>
          <div class="text-sm" style="color: var(--text);">${negotiation.顧客名 || ''}</div>
        </div>
        <div>
          <div class="text-xs" style="color: var(--text-muted);">商品名</div>
          <div class="text-sm" style="color: var(--text);">${negotiation.商品名 || ''}</div>
        </div>
        <div class="grid grid-cols-2 gap-2">
          <div>
            <div class="text-xs" style="color: var(--text-muted);">現在単価</div>
            <div class="text-sm" style="color: var(--text);">${negotiation.現在単価 ? negotiation.現在単価.toLocaleString() + '円' : ''}</div>
          </div>
          <div>
            <div class="text-xs" style="color: var(--text-muted);">提案単価</div>
            <div class="text-sm" style="color: var(--text);">${negotiation.提案単価 ? negotiation.提案単価.toLocaleString() + '円' : ''}</div>
          </div>
        </div>
        <div>
          <div class="text-xs" style="color: var(--text-muted);">交渉内容</div>
          <div class="text-sm" style="color: var(--text);">${negotiation.交渉内容 || ''}</div>
        </div>
        <div>
          <div class="text-xs" style="color: var(--text-muted);">次回アクション</div>
          <div class="text-sm" style="color: var(--text);">${negotiation.次回アクション || ''}</div>
        </div>
      </div>
    `;
    drawPriceChart(negotiation);
  }

  // 価格推移グラフ描画
  function drawPriceChart(negotiation) {
    ctx.clearRect(0, 0, priceChart.width, priceChart.height);

    const current = negotiation.現在単価 || 0;
    const proposed = negotiation.提案単価 || 0;
    const agreed = negotiation.合意単価 || 0;

    const maxPrice = Math.max(current, proposed, agreed) * 1.1;
    const minPrice = Math.min(current, proposed, agreed) * 0.9;
    const range = maxPrice - minPrice;

    // グリッド線
    ctx.strokeStyle = '#e5e7eb';
    ctx.lineWidth = 1;
    for (let i = 0; i <= 4; i++) {
      const y = 30 + (i * 30);
      ctx.beginPath();
      ctx.moveTo(40, y);
      ctx.lineTo(280, y);
      ctx.stroke();
    }

    // データポイント
    const points = [
      { x: 80, y: 150 - ((current - minPrice) / range) * 120, label: '現在', value: current, color: '#6b7280' },
      { x: 150, y: 150 - ((proposed - minPrice) / range) * 120, label: '提案', value: proposed, color: '#3b82f6' },
      { x: 220, y: 150 - ((agreed - minPrice) / range) * 120, label: '合意', value: agreed, color: '#22c55e' }
    ];

    // 線を描画
    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(points[0].x, points[0].y);
    ctx.lineTo(points[1].x, points[1].y);
    ctx.lineTo(points[2].x, points[2].y);
    ctx.stroke();

    // ポイントを描画
    points.forEach(point => {
      ctx.fillStyle = point.color;
      ctx.beginPath();
      ctx.arc(point.x, point.y, 4, 0, 2 * Math.PI);
      ctx.fill();

      // ラベル
      ctx.fillStyle = '#374151';
      ctx.font = '10px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(point.label, point.x, point.y - 10);
      ctx.fillText(point.value.toLocaleString() + '円', point.x, point.y + 20);
    });
  }

  // 2. 初期データ描画
  renderRows(tables[0].records || []);

  // 3. 検索機能
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const customer = container.querySelector('#customer-filter').value;
    const category = container.querySelector('#category-filter').value;
    const status = container.querySelector('#status-filter').value;
    const dateFrom = container.querySelector('#date-from').value;
    const dateTo = container.querySelector('#date-to').value;

    const rows = await window.aivicApi.list(0);
    if (!rows) return;

    const filtered = rows.filter(r => {
      if (customer && r.顧客ID !== customer) return false;
      if (category && r.商品カテゴリ !== category) return false;
      if (status && r.交渉ステータス !== status) return false;
      if (dateFrom && new Date(r.交渉日) < new Date(dateFrom)) return false;
      if (dateTo && new Date(r.交渉日) > new Date(dateTo)) return false;
      return true;
    });

    renderRows(filtered);
  });

  // 4. 新規交渉記録
  const modal = container.querySelector('#new-negotiation-modal');

  container.querySelector('#btn-new-negotiation').addEventListener('click', () => {
    modal.style.display = 'flex';
  });

  container.querySelector('#btn-modal-cancel').addEventListener('click', () => {
    modal.style.display = 'none';
  });

  container.querySelector('#btn-modal-save').addEventListener('click', async () => {
    const customer = container.querySelector('#modal-customer').value;
    const product = container.querySelector('#modal-product').value;
    const currentPrice = parseInt(container.querySelector('#modal-current-price').value) || 0;
    const proposedPrice = parseInt(container.querySelector('#modal-proposed-price').value) || 0;
    const negotiationType = container.querySelector('#modal-negotiation-type').value;
    const content = container.querySelector('#modal-negotiation-content').value;

    if (!customer || !product) {
      alert('顧客と商品を選択してください');
      return;
    }

    const saved = await window.aivicApi.save(0, {
      顧客ID: customer,
      商品ID: product,
      交渉日: new Date().toISOString(),
      交渉種別: negotiationType,
      現在単価: currentPrice,
      提案単価: proposedPrice,
      交渉ステータス: '交渉中',
      交渉内容: content,
      営業担当者ID: 'user-001',
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString(),
      作成者ID: 'user-001'
    });

    if (saved) {
      modal.style.display = 'none';
      const rows = await window.aivicApi.list(0);
      if (rows) renderRows(rows);
    }
  });

  // 5. 行レベル操作
  container.addEventListener('click', async (e) => {
    // 行クリックで詳細表示
    const row = e.target.closest('tr[data-id]');
    if (row && !e.target.closest('button')) {
      const id = row.dataset.id;
      const rows = await window.aivicApi.list(0);
      if (rows) {
        const negotiation = rows.find(r => r.id === id);
        if (negotiation) showDetail(negotiation);
      }
    }

    // 削除ボタン
    const deleteBtn = e.target.closest('.delete-btn');
    if (deleteBtn) {
      if (!confirm('この交渉履歴を削除しますか？')) return;
      await window.aivicApi.delete(0, deleteBtn.dataset.id);
      const rows = await window.aivicApi.list(0);
      if (rows) renderRows(rows);
    }

    // 編集ボタン
    const editBtn = e.target.closest('.edit-btn');
    if (editBtn) {
      const rows = await window.aivicApi.list(0);
      if (rows) {
        const negotiation = rows.find(r => r.id === editBtn.dataset.id);
        if (negotiation) {
          container.querySelector('#modal-customer').value = negotiation.顧客ID || '';
          container.querySelector('#modal-product').value = negotiation.商品ID || '';
          container.querySelector('#modal-current-price').value = negotiation.現在単価 || '';
          container.querySelector('#modal-proposed-price').value = negotiation.提案単価 || '';
          container.querySelector('#modal-negotiation-type').value = negotiation.交渉種別 || '';
          container.querySelector('#modal-negotiation-content').value = negotiation.交渉内容 || '';
          modal.style.display = 'flex';
        }
      }
    }
  });

  // CSVエクスポート
  container.querySelector('#btn-csv-export').addEventListener('click', async () => {
    const rows = await window.aivicApi.list(0);
    if (!rows) return;

    const headers = ['交渉日', '顧客名', '商品名', '現在単価', '提案単価', '合意単価', 'ステータス', '交渉内容'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...rows.map(r => [
        r.交渉日 || '',
        r.顧客名 || '',
        r.商品名 || '',
        r.現在単価 || '',
        r.提案単価 || '',
        r.合意単価 || '',
        r.交渉ステータス || '',
        `"${(r.交渉内容 || '').replace(/"/g, '""')}"`
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = '単価交渉履歴_' + new Date().toISOString().slice(0, 10) + '.csv';
    link.click();
  });
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector('#price-data-tbody');
  const form = container.querySelector('#price-form');
  const formTitle = container.querySelector('#form-title');
  const editIdInput = container.querySelector('#edit-id');
  const saveBtn = container.querySelector('#btn-save');
  const updateBtn = container.querySelector('#btn-update');
  const deleteBtn = container.querySelector('#btn-delete');

  // 1. テーブル再描画関数
  function renderRows(rows) {
    tbody.innerHTML = rows.map(row => `
      <tr data-id="${row.id}" style="cursor: pointer;">
        <td>${row.商品コード || ''}</td>
        <td>${row.商品名 || ''}</td>
        <td style="text-align: right;">${row.市場価格 ? row.市場価格.toLocaleString() + '円' : ''}</td>
        <td>${row.価格情報源 || ''}</td>
        <td>${row.地域 || ''}</td>
        <td>${row.価格取得日 ? new Date(row.価格取得日).toLocaleDateString('ja-JP') : ''}</td>
        <td>
          <span style="padding: 2px 6px; border-radius: 3px; font-size: 11px; ${row.有効フラグ ? 'background: rgba(34, 197, 94, 0.1); color: #16a34a;' : 'background: rgba(239, 68, 68, 0.1); color: #dc2626;'}">
            ${row.有効フラグ ? '有効' : '無効'}
          </span>
        </td>
        <td>
          <button class="action-btn secondary edit-btn" data-id="${row.id}" style="font-size: 11px; padding: 2px 6px;">編集</button>
        </td>
      </tr>
    `).join('');
  }

  // 2. 初期データ描画
  renderRows(tables[0].records || []);

  // 3. 検索機能
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const keyword = container.querySelector('#search-keyword').value.toLowerCase();
    const sourceFilter = container.querySelector('#filter-source').value;
    const regionFilter = container.querySelector('#filter-region').value;

    const rows = await window.aivicApi.list(0);
    if (rows) {
      const filtered = rows.filter(row => {
        const matchKeyword = !keyword || 
          (row.商品コード && row.商品コード.toLowerCase().includes(keyword)) ||
          (row.商品名 && row.商品名.toLowerCase().includes(keyword));
        const matchSource = !sourceFilter || row.価格情報源 === sourceFilter;
        const matchRegion = !regionFilter || row.地域 === regionFilter;
        return matchKeyword && matchSource && matchRegion;
      });
      renderRows(filtered);
    }
  });

  // 4. 登録機能
  form.addEventListener('submit', async (e) => {
    e.preventDefault();
    const formData = new FormData(form);
    const data = {
      商品コード: formData.get('product_code'),
      商品名: formData.get('product_name'),
      市場価格: parseInt(formData.get('market_price')),
      価格取得日: formData.get('price_date'),
      価格情報源: formData.get('price_source'),
      地域: formData.get('region'),
      備考: formData.get('remarks'),
      有効フラグ: true,
      作成者: 'システム管理者'
    };

    const saved = await window.aivicApi.save(0, data);
    if (saved) {
      form.reset();
      const rows = await window.aivicApi.list(0);
      if (rows) renderRows(rows);
    }
  });

  // 5. 更新機能
  updateBtn.addEventListener('click', async () => {
    const id = editIdInput.value;
    if (!id) return;

    const formData = new FormData(form);
    const data = {
      商品コード: formData.get('product_code'),
      商品名: formData.get('product_name'),
      市場価格: parseInt(formData.get('market_price')),
      価格取得日: formData.get('price_date'),
      価格情報源: formData.get('price_source'),
      地域: formData.get('region'),
      備考: formData.get('remarks'),
      有効フラグ: true
    };

    const updated = await window.aivicApi.update(0, id, data);
    if (updated) {
      clearForm();
      const rows = await window.aivicApi.list(0);
      if (rows) renderRows(rows);
    }
  });

  // 6. 削除機能
  deleteBtn.addEventListener('click', async () => {
    const id = editIdInput.value;
    if (!id || !confirm('この価格データを削除しますか？')) return;

    await window.aivicApi.delete(0, id);
    clearForm();
    const rows = await window.aivicApi.list(0);
    if (rows) renderRows(rows);
  });

  // 7. 行クリック・編集ボタンのイベントデリゲーション
  container.addEventListener('click', async (e) => {
    const editBtn = e.target.closest('.edit-btn');
    const row = e.target.closest('tr[data-id]');

    if (editBtn || (row && !e.target.closest('button'))) {
      const id = editBtn ? editBtn.dataset.id : row.dataset.id;
      const rows = await window.aivicApi.list(0);
      if (rows) {
        const record = rows.find(r => r.id === id);
        if (record) {
          editIdInput.value = id;
          container.querySelector('#product-code').value = record.商品コード || '';
          container.querySelector('#product-name').value = record.商品名 || '';
          container.querySelector('#market-price').value = record.市場価格 || '';
          container.querySelector('#price-date').value = record.価格取得日 ? record.価格取得日.split('T')[0] : '';
          container.querySelector('#price-source').value = record.価格情報源 || '';
          container.querySelector('#region').value = record.地域 || '';
