function(container, apiUrl, tables) {
  // チャート描画関数
  function drawAmountChart() {
    const canvas = container.querySelector('#amount-chart');
    const ctx = canvas.getContext('2d');

    // キャンバスクリア
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // データ
    const months = ['8月', '9月', '10月', '11月', '12月'];
    const amounts = [9800000, 10500000, 11200000, 11800000, 12450000];

    // グラフエリア設定
    const padding = 40;
    const graphWidth = canvas.width - padding * 2;
    const graphHeight = canvas.height - padding * 2;

    // 軸描画
    ctx.strokeStyle = '#9ca3af';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // データ線描画
    ctx.strokeStyle = '#22c55e';
    ctx.lineWidth = 2;
    ctx.beginPath();

    const maxAmount = Math.max(...amounts);
    const minAmount = Math.min(...amounts);
    const range = maxAmount - minAmount;

    amounts.forEach((amount, i) => {
      const x = padding + (graphWidth / (amounts.length - 1)) * i;
      const y = canvas.height - padding - ((amount - minAmount) / range) * graphHeight;

      if (i === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }

      // データポイント
      ctx.fillStyle = '#22c55e';
      ctx.beginPath();
      ctx.arc(x, y, 3, 0, Math.PI * 2);
      ctx.fill();
    });
    ctx.stroke();

    // ラベル
    ctx.fillStyle = '#6b7280';
    ctx.font = '10px sans-serif';
    ctx.textAlign = 'center';
    months.forEach((month, i) => {
      const x = padding + (graphWidth / (amounts.length - 1)) * i;
      ctx.fillText(month, x, canvas.height - 10);
    });
  }

  function drawPriceChart() {
    const canvas = container.querySelector('#price-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const months = ['8月', '9月', '10月', '11月', '12月'];
    const ourPrices = [82000, 81500, 80800, 80200, 79807];
    const marketPrices = [85000, 84200, 83800, 83500, 83200];

    const padding = 40;
    const graphWidth = canvas.width - padding * 2;
    const graphHeight = canvas.height - padding * 2;

    // 軸描画
    ctx.strokeStyle = '#9ca3af';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    const allPrices = [...ourPrices, ...marketPrices];
    const maxPrice = Math.max(...allPrices);
    const minPrice = Math.min(...allPrices);
    const range = maxPrice - minPrice;

    // 自社価格線
    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ourPrices.forEach((price, i) => {
      const x = padding + (graphWidth / (ourPrices.length - 1)) * i;
      const y = canvas.height - padding - ((price - minPrice) / range) * graphHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // 市場価格線
    ctx.strokeStyle = '#ef4444';
    ctx.lineWidth = 2;
    ctx.beginPath();
    marketPrices.forEach((price, i) => {
      const x = padding + (graphWidth / (marketPrices.length - 1)) * i;
      const y = canvas.height - padding - ((price - minPrice) / range) * graphHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // 凡例
    ctx.fillStyle = '#3b82f6';
    ctx.fillRect(10, 10, 12, 8);
    ctx.fillStyle = '#6b7280';
    ctx.font = '10px sans-serif';
    ctx.fillText('自社価格', 25, 18);

    ctx.fillStyle = '#ef4444';
    ctx.fillRect(10, 25, 12, 8);
    ctx.fillStyle = '#6b7280';
    ctx.fillText('市場価格', 25, 33);
  }

  // 商品別データ再描画
  function renderProductData(data) {
    const tbody = container.querySelector('#product-tbody');
    tbody.innerHTML = data.map(item => `
      <tr>
        <td>${item.商品コード || ''}</td>
        <td>${item.商品名 || ''}</td>
        <td>${item.発注数量 || 0}個</td>
        <td>¥${(item.発注金額 || 0).toLocaleString()}</td>
        <td>¥${(item.平均単価 || 0).toLocaleString()}</td>
        <td style="color: ${(item.市場価格差異率 || 0) < 0 ? '#22c55e' : '#ef4444'};">${(item.市場価格差異率 || 0) > 0 ? '+' : ''}${item.市場価格差異率 || 0}%</td>
        <td style="color: ${(item.前年同月比 || 0) > 0 ? '#22c55e' : '#ef4444'};">${(item.前年同月比 || 0) > 0 ? '+' : ''}${item.前年同月比 || 0}%</td>
      </tr>
    `).join('');
  }

  // 初期データ表示
  renderProductData(tables[5]?.records || []);

  // チャート初期描画
  setTimeout(() => {
    drawAmountChart();
    drawPriceChart();
  }, 100);

  // 分析実行ボタン
  container.querySelector('#btn-analyze').addEventListener('click', async () => {
    const customerId = container.querySelector('#customer-filter').value;
    const targetMonth = container.querySelector('#target-month').value;
    const period = container.querySelector('#period-filter').value;

    // 月次集計データを取得して分析
    const monthlyData = await window.aivicApi.list(4);
    if (monthlyData) {
      // フィルタリング処理
      let filteredData = monthlyData;
      if (customerId) {
        filteredData = filteredData.filter(item => item.顧客ID === customerId);
      }

      // KPI更新（実際のデータに基づく）
      const totalAmount = filteredData.reduce((sum, item) => sum + (item.発注金額 || 0), 0);
      const totalCount = filteredData.reduce((sum, item) => sum + (item.発注件数 || 0), 0);

      container.querySelector('[data-testid="total-amount"]').textContent = `¥${totalAmount.toLocaleString()}`;
      container.querySelector('[data-testid="order-count"]').textContent = `${totalCount}件`;

      // チャート再描画
      drawAmountChart();
      drawPriceChart();
    }
  });

  // CSV出力
  container.querySelector('#btn-export').addEventListener('click', async () => {
    const data = await window.aivicApi.list(5);
    if (!data) return;

    const headers = ['商品コード', '商品名', '発注数量', '発注金額', '平均単価', '市場価格差異率', '前年同月比'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...data.map(row => [
        row.商品コード || '',
        row.商品名 || '',
        row.発注数量 || 0,
        row.発注金額 || 0,
        row.平均単価 || 0,
        row.市場価格差異率 || 0,
        row.前年同月比 || 0
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `顧客別発注データ_${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
  });

  // 画面遷移
  container.querySelector('[data-testid="category-analysis-btn"]').addEventListener('click', () => {
    window.showScreen("scr-1780316163114");
  });

  container.querySelector('[data-testid="price-comparison-btn"]').addEventListener('click', () => {
    window.showScreen("scr-1780316174750");
  });
