function(container, apiUrl, tables) {
  // チャート描画関数
  function drawFactorsChart() {
    const canvas = container.querySelector('#factors-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const factors = [
      { name: '競合価格調査済み', rate: 85.2 },
      { name: '長期契約提案', rate: 78.9 },
      { name: '数量割引適用', rate: 72.4 },
      { name: '市場価格未調査', rate: 32.1 },
      { name: '単発取引', rate: 41.5 }
    ];

    const barHeight = 30;
    const barSpacing = 10;
    const startY = 40;
    const maxWidth = 300;

    ctx.font = '12px sans-serif';
    ctx.fillStyle = '#6b7280';
    ctx.fillText('成功率 (%)', 10, 25);

    factors.forEach((factor, index) => {
      const y = startY + index * (barHeight + barSpacing);
      const barWidth = (factor.rate / 100) * maxWidth;

      // バー描画
      ctx.fillStyle = factor.rate > 60 ? '#22c55e' : '#ef4444';
      ctx.fillRect(80, y, barWidth, barHeight);

      // ラベル
      ctx.fillStyle = '#374151';
      ctx.font = '11px sans-serif';
      ctx.fillText(factor.name, 10, y + 20);

      // 数値
      ctx.fillStyle = '#6b7280';
      ctx.fillText(factor.rate + '%', barWidth + 85, y + 20);
    });
  }

  function drawPriceTrendChart() {
    const canvas = container.querySelector('#price-trend-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const months = ['1月', '2月', '3月', '4月', '5月', '6月'];
    const products = [
      { name: '電子部品A', data: [100, 98, 102, 105, 103, 107], color: '#3b82f6' },
      { name: '機械部品B', data: [150, 148, 145, 152, 155, 158], color: '#22c55e' },
      { name: '化学製品C', data: [80, 82, 85, 83, 88, 90], color: '#f59e0b' }
    ];

    const chartArea = { x: 50, y: 30, width: 320, height: 180 };

    // 軸描画
    ctx.strokeStyle = '#e5e7eb';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(chartArea.x, chartArea.y);
    ctx.lineTo(chartArea.x, chartArea.y + chartArea.height);
    ctx.lineTo(chartArea.x + chartArea.width, chartArea.y + chartArea.height);
    ctx.stroke();

    // 月ラベル
    ctx.fillStyle = '#6b7280';
    ctx.font = '10px sans-serif';
    months.forEach((month, index) => {
      const x = chartArea.x + (index * chartArea.width / (months.length - 1));
      ctx.fillText(month, x - 10, chartArea.y + chartArea.height + 15);
    });

    // データ線描画
    products.forEach(product => {
      ctx.strokeStyle = product.color;
      ctx.lineWidth = 2;
      ctx.beginPath();

      product.data.forEach((value, index) => {
        const x = chartArea.x + (index * chartArea.width / (product.data.length - 1));
        const y = chartArea.y + chartArea.height - ((value - 70) / 100 * chartArea.height);

        if (index === 0) {
          ctx.moveTo(x, y);
        } else {
          ctx.lineTo(x, y);
        }
      });
      ctx.stroke();
    });

    // 凡例
    products.forEach((product, index) => {
      const legendY = chartArea.y + chartArea.height + 35 + (index * 15);
      ctx.fillStyle = product.color;
      ctx.fillRect(chartArea.x, legendY, 10, 10);
      ctx.fillStyle = '#374151';
      ctx.font = '10px sans-serif';
      ctx.fillText(product.name, chartArea.x + 15, legendY + 8);
    });
  }

  function drawMarketDeviationChart() {
    const canvas = container.querySelector('#market-deviation-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const data = [
      { category: '電子部品', deviation: -2.1 },
      { category: '機械部品', deviation: 1.5 },
      { category: '化学製品', deviation: -0.8 },
      { category: '建材', deviation: 3.2 }
    ];

    const chartArea = { x: 80, y: 30, width: 280, height: 180 };
    const barHeight = 30;

    // 軸描画
    ctx.strokeStyle = '#e5e7eb';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(chartArea.x + chartArea.width/2, chartArea.y);
    ctx.lineTo(chartArea.x + chartArea.width/2, chartArea.y + chartArea.height);
    ctx.stroke();

    data.forEach((item, index) => {
      const y = chartArea.y + 20 + index * 45;
      const barWidth = Math.abs(item.deviation) * 20;
      const x = item.deviation > 0 ? chartArea.x + chartArea.width/2 : chartArea.x + chartArea.width/2 - barWidth;

      // バー描画
      ctx.fillStyle = item.deviation > 0 ? '#ef4444' : '#22c55e';
      ctx.fillRect(x, y, barWidth, barHeight);

      // カテゴリ名
      ctx.fillStyle = '#374151';
      ctx.font = '11px sans-serif';
      ctx.fillText(item.category, 10, y + 20);

      // 数値
      ctx.fillStyle = '#6b7280';
      ctx.fillText(item.deviation > 0 ? '+' + item.deviation + '%' : item.deviation + '%', 
                   chartArea.x + chartArea.width - 40, y + 20);
    });
  }

  function drawTimingChart() {
    const canvas = container.querySelector('#timing-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const timings = [
