      const y = chartArea.y + chartArea.height - barHeight;

      // バー描画
      ctx.fillStyle = '#3b82f6';
      ctx.fillRect(x, y, barWidth, barHeight);

      // ラベル
      ctx.fillStyle = '#374151';
      ctx.font = '11px sans-serif';
      ctx.fillText(timing.period, x + 15, chartArea.y + chartArea.height + 15);

      // 成功率
      ctx.fillStyle = '#6b7280';
      ctx.font = '10px sans-serif';
      ctx.fillText(timing.success + '%', x + 20, y - 5);

      // 件数
      ctx.fillText('(' + timing.total + '件)', x + 10, chartArea.y + chartArea.height + 30);
    });
  }

  // 初期チャート描画
  setTimeout(() => {
    drawFactorsChart();
    drawPriceTrendChart();
