function(container, apiUrl, tables) {
  // チャート描画関数
  function drawPatternChart() {
    const canvas = container.querySelector('#pattern-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 背景
    ctx.fillStyle = '#f8fafc';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // データ
    const months = ['1月', '2月', '3月', '4月', '5月', '6月'];
    const data = [120, 135, 150, 140, 165, 180];
    const max = Math.max(...data);

    // 軸
    ctx.strokeStyle = '#64748b';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(40, 20);
    ctx.lineTo(40, 160);
    ctx.lineTo(360, 160);
    ctx.stroke();

    // 線グラフ
    ctx.strokeStyle = '#22c55e';
    ctx.lineWidth = 2;
    ctx.beginPath();

    data.forEach((value, i) => {
      const x = 60 + (i * 50);
      const y = 160 - (value / max * 120);

      if (i === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }

      // ポイント
      ctx.fillStyle = '#22c55e';
      ctx.beginPath();
      ctx.arc(x, y, 3, 0, 2 * Math.PI);
      ctx.fill();
    });

    ctx.stroke();

    // ラベル
    ctx.fillStyle = '#475569';
    ctx.font = '12px sans-serif';
    months.forEach((month, i) => {
      ctx.fillText(month, 50 + (i * 50), 175);
    });
  }

  function drawSalesChart() {
    const canvas = container.querySelector('#sales-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 背景
    ctx.fillStyle = '#f8fafc';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // データ
    const months = ['1月', '2月', '3月', '4月', '5月', '6月'];
    const sales = [2500, 2800, 3200, 2900, 3500, 3800];
    const max = Math.max(...sales);

    // 軸
    ctx.strokeStyle = '#64748b';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(40, 20);
    ctx.lineTo(40, 160);
    ctx.lineTo(360, 160);
    ctx.stroke();

    // 棒グラフ
    sales.forEach((value, i) => {
      const x = 60 + (i * 45);
      const height = (value / max) * 120;
      const y = 160 - height;

      ctx.fillStyle = '#22c55e';
      ctx.fillRect(x, y, 35, height);

      // 値表示
      ctx.fillStyle = '#475569';
      ctx.font = '10px sans-serif';
      ctx.fillText(value + '万', x, y - 5);
    });

    // ラベル
    ctx.fillStyle = '#475569';
    ctx.font = '12px sans-serif';
    months.forEach((month, i) => {
      ctx.fillText(month, 65 + (i * 45), 175);
    });
  }

  function drawPriceDistributionChart() {
    const canvas = container.querySelector('#price-distribution-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 背景
    ctx.fillStyle = '#f8fafc';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // 円グラフ
    const data = [
      { label: '~10万', value: 30, color: '#22c55e' },
      { label: '10-50万', value: 45, color: '#16a34a' },
      { label: '50-100万', value: 20, color: '#15803d' },
      { label: '100万~', value: 5, color: '#166534' }
    ];

    const centerX = 200;
    const centerY = 100;
    const radius = 60;
    let currentAngle = 0;

    data.forEach(item => {
      const sliceAngle = (item.value / 100) * 2 * Math.PI;

      ctx.fillStyle = item.color;
      ctx.beginPath();
      ctx.moveTo(centerX, centerY);
      ctx.arc(centerX, centerY, radius, currentAngle, currentAngle + sliceAngle);
      ctx.closePath();
      ctx.fill();

      // ラベル
      const labelAngle = currentAngle + sliceAngle / 2;
      const labelX = centerX + Math.cos(labelAngle) * (radius + 20);
      const labelY = centerY + Math.sin(labelAngle) * (radius + 20);

      ctx.fillStyle = '#475569';
      ctx.font = '11px sans-serif';
      ctx.fillText(item.label, labelX - 15, labelY);
      ctx.fillText(item.value + '%', labelX - 10, labelY + 12);

      currentAngle += sliceAngle;
    });
  }

  function drawCompetitorChart() {
    const canvas = container.querySelector('#competitor-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 背景
    ctx.fillStyle = '#f8fafc';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // データ
    const categories = ['電子部品', '機械部品', '化学製品', '建材', '工具'];
    const ourPrice = [150, 280, 120, 350, 80];
    const competitorA = [160, 270, 130, 340, 85];
    const competitorB = [145, 290, 115, 360, 75];

    const max = Math.max(...ourPrice, ...competitorA, ...competitorB);

    // 軸
    ctx.strokeStyle = '#64748b';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(60, 20);
    ctx.lineTo(60, 250);
    ctx.lineTo(740, 250);
    ctx.stroke();

    // 棒グラフ
    categories.forEach((category, i) => {
      const x = 100 + (i * 120);

      // 自社価格
      const ourHeight = (ourPrice[i] / max) * 200;
      ctx.fillStyle = '#22c55e';
      ctx.fillRect(x, 250 - ourHeight, 25, ourHeight);

      // 競合A
      const aHeight = (competitorA[i] / max) * 200;
      ctx.fillStyle = '#f59e0b';
      ctx.fillRect(x + 30, 250 - aHeight, 25, aHeight);

      // 競合B
      const bHeight = (competitorB[i] / max) * 200;
      ctx.fillStyle = '#ef4444';
      ctx.fillRect(x + 60, 250 - bHeight, 25, bHeight);

      // カテゴリ名
      ctx.fillStyle = '#475569';
      ctx.font = '12px sans-serif';
      ctx.fillText(category, x + 10, 270);
    });

    // 凡例
    ctx.fillStyle = '#22c55e';
    ctx.fillRect(100, 290, 15, 15);
    ctx.fillStyle = '#475569';
    ctx.fillText('自社', 120, 302);

    ctx.fillStyle = '#f59e0b';
    ctx.fillRect(180, 290, 15, 15);
    ctx.fillText('競合A', 200, 302);

    ctx.fillStyle = '#ef4444';
    ctx.fillRect(260, 290, 15, 15);
    ctx.fillText('競合B', 280, 302);
  }

  function updateKPIs(data) {
    const totalSales = data.reduce((sum, item) => sum + (item.総購買金額 || 0), 0);
    const avgPrice = data.reduce((sum, item) => sum + (item.平均発注金額 || 0), 0) / data.length || 0;
    const orderCount = data.reduce((sum, item) => sum + (item.購買頻度 || 0), 0);
    const avgNegotiationRate = data.reduce((sum, item) => sum + (item.交渉成功率 || 0), 0) / data.length || 0;

    container.querySelector('#kpi-total-sales').textContent = '¥' + totalSales.toLocaleString();
    container.querySelector('#kpi-avg-price').textContent = '¥' + Math.round(avgPrice).toLocaleString();
    container.querySelector('#kpi-order-count').textContent = orderCount.toLocaleString();
    container.querySelector('#kpi-negotiation-rate').textContent = Math.round(avgNegotiationRate) + '%';
  }

  function renderSegmentTable(data) {
    const tbody = container.querySelector('#segment-tbody');
    if (!data || data.length === 0) return;

    const segmentData = {};
    data.forEach(item => {
      const rank = item.顧客ランク || 'その他';
      if (!segmentData[rank]) {
        segmentData[rank] = {
          frequency: 0,
          avgAmount: 0,
          sensitivity: item.価格感度 || '中',
          approach: item.推奨営業アプローチ || 'バランス戦略',
          count: 0
        };
      }
      segmentData[rank].frequency += item.購買頻度 || 0;
      segmentData[rank].avgAmount += item.平均発注金額 || 0;
      segmentData[rank].count++;
    });

    tbody.innerHTML = Object.entries(segmentData).map(([rank, data]) => `
      <tr>
        <td>${rank}</td>
        <td>月${Math.round(data.frequency / data.count)}回</td>
        <td>¥${Math.round(data.avgAmount / data.count).toLocaleString()}</td>
        <td>${data.sensitivity}</td>
        <td>${data.approach}</td>
      </tr>
    `).join('');
  }

  // 初期データ読み込み
  async function loadData() {
    try {
      const analysisData = await window.aivicApi.list(2); // 購買パターン分析結果
      const strategyData = await window.aivicApi.list(3); // 価格戦略分析結果

      if (analysisData) {
        updateKPIs(analysisData);
        renderSegmentTable(analysisData);
      }

      // チャート描画
      drawPatternChart();
      drawSalesChart();
      drawPriceDistributionChart();
      drawCompetitorChart();

    } catch (error) {
      console.error('データ読み込みエラー:', error);
    }
  }

  // 分析実行
  container.querySelector('#btn-analyze').addEventListener('click', async () => {
    const category = container.querySelector('#select-category').value;
    const startDate = container.querySelector('#input-start-date').value;
    const endDate = container.querySelector('#input-end-date').value;

    // 分析条件に基づいてデータを再取得・再描画
    await loadData();
  });

  // データエクスポート
  container.querySelector('#btn-export').addEventListener('click', async () => {
    try {
      const data = await window.aivicApi.list(2);
      if (!data) return;

      const headers = ['顧客ID', '分析期間開始日', '分析期間終了日', '購買頻度', '平均発注金額', '総購買金額', '主要購買商品カテゴリ', '価格感度', '顧客ランク'];
      const csvContent = '\uFEFF' + headers.join(',') + '\n' + 
        data.map(row => [
          row.顧客ID || '',
          row.分析期間開始日 || '',
          row.分析期間終了日 || '',
          row.購買頻度 || '',
          row.平均発注金額 || '',
          row.総購買金額 || '',
          row.主要購買商品カテゴリ || '',
          row.価格感度 || '',
          row.顧客ランク || ''
        ].join(',')).join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = '購買パターン分析_' + new Date().toISOString().slice(0, 10) + '.csv';
      link.click();
    } catch (error) {
      console.error('エクスポートエラー:', error);
    }
  });

  // 分析レポート生成
  container.querySelector('#btn-generate-report').addEventListener('click', () => {
    alert('分析レポートを生成しました。ダウンロードを開始します。');
  });

  // 価格戦略提案画面への遷移
  container.querySelector('#btn-price-strategy').addEventListener('click', () => {
    window.showScreen("scr-1780316183885");
  });

  // 初期データ読み込み
  loadData();

  // 初期日付設定
  const today = new Date();
  const sixMonthsAgo = new Date(today.getFullYear(), today.getMonth() - 6, today.getDate());
  container.querySelector('#input-start-date').value = sixMonthsAgo.toISOString().slice(0, 10);
  container.querySelector('#input-end-date').value = today.toISOString().slice(0, 10);
}

function(container, apiUrl, tables) {
  // テーブル再描画関数
  function renderCustomerPrices(rows) {
    const tbody = container.querySelector("#customer-price-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td>${r.顧客名 || ""}</td>
        <td>${r.商品名 || ""}</td>
        <td>¥${(r.現在単価 || 0).toLocaleString()}</td>
        <td style="color: ${r.市場価格差異率 > 0 ? '#ef4444' : '#22c55e'}">${r.市場価格差異率 > 0 ? '+' : ''}${r.市場価格差異率 || 0}%</td>
      </tr>
    `).join("");
  }

  function renderNegotiationHistory(rows) {
    const tbody = container.querySelector("#negotiation-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td>${r.交渉日 ? new Date(r.交渉日).toLocaleDateString('ja-JP') : ""}</td>
        <td>${r.顧客名 || ""}</td>
        <td>¥${(r.提案単価 || 0).toLocaleString()}</td>
        <td>
          <span class="px-2 py-1 rounded text-xs" style="background: ${getStatusColor(r.交渉ステータス).bg}; color: ${getStatusColor(r.交渉ステータス).text}">
            ${r.交渉ステータス || ""}
          </span>
        </td>
      </tr>
    `).join("");
  }

  function getStatusColor(status) {
    switch(status) {
      case '合意': return { bg: 'rgba(34, 197, 94, 0.2)', text: '#22c55e' };
      case '決裂': return { bg: 'rgba(239, 68, 68, 0.2)', text: '#ef4444' };
      case '交渉中': return { bg: 'rgba(59, 130, 246, 0.2)', text: '#3b82f6' };
      default: return { bg: 'rgba(156, 163, 175, 0.2)', text: '#6b7280' };
    }
  }

  // チャート描画関数
  function drawMarketChart() {
    const canvas = container.querySelector("#market-chart");
    const ctx = canvas.getContext("2d");

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 棒グラフ（市場価格 vs 自社価格）
    const data = [
      { label: "電子部品", market: 1000, our: 1150 },
      { label: "機械部品", market: 2350, our: 2300 },
      { label: "化学製品", market: 800, our: 850 }
    ];

    const barWidth = 25;
    const spacing = 20;

    data.forEach((item, i) => {
      const x = 20 + i * (barWidth * 2 + spacing);
      const maxPrice = Math.max(item.market, item.our);
      const marketHeight = (item.market / maxPrice) * 80;
      const ourHeight = (item.our / maxPrice) * 80;

      // 市場価格（青）
      ctx.fillStyle = '#3b82f6';
      ctx.fillRect(x, 100 - marketHeight, barWidth, marketHeight);

      // 自社価格（緑）
      ctx.fillStyle = '#22c55e';
      ctx.fillRect(x + barWidth, 100 - ourHeight, barWidth, ourHeight);
    });

    // 凡例
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '10px sans-serif';
    ctx.fillText('市場価格', 10, 115);
    ctx.fillText('自社価格', 70, 115);
  }

  function drawTrendChart() {
    const canvas = container.querySelector("#trend-chart");
    const ctx = canvas.getContext("2d");

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 折れ線グラフ（月次推移）
    const months = ['10月', '11月', '12月', '1月'];
    const avgPrices = [1050, 1080, 1120, 1150];

    ctx.strokeStyle = '#22c55e';
    ctx.lineWidth = 2;
    ctx.beginPath();

    avgPrices.forEach((price, i) => {
      const x = 20 + i * 40;
      const y = 100 - ((price - 1000) / 200) * 80;

      if (i === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }

      // データポイント
      ctx.fillStyle = '#22c55e';
      ctx.fillRect(x - 2, y - 2, 4, 4);
    });

    ctx.stroke();

    // 月ラベル
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '10px sans-serif';
    months.forEach((month, i) => {
      ctx.fillText(month, 15 + i * 40, 115);
    });
  }

  // 初期データ描画
  if (tables[0] && tables[0].records) {
    renderCustomerPrices(tables[0].records);
  }
  if (tables[1] && tables[1].records) {
    renderNegotiationHistory(tables[1].records);
  }

  // チャート初期描画
  setTimeout(() => {
    drawMarketChart();
    drawTrendChart();
  }, 100);

  // 分析実行ボタン
  container.querySelector("#btn-analyze").addEventListener("click", async () => {
    const customerId = container.querySelector("#customer-select").value;
    const category = container.querySelector("#category-select").value;
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;

    // 顧客別分析データを取得・更新
    const customerData = await window.aivicApi.list(5); // 顧客別分析データ
    if (customerData) {
      let filteredData = customerData;

      if (customerId) {
        filteredData = filteredData.filter(r => r.顧客ID === customerId);
      }

      renderCustomerPrices(filteredData);
    }

    // 交渉履歴を取得・更新
    const negotiationData = await window.aivicApi.list(0); // 単価交渉履歴
    if (negotiationData) {
      let filteredNegotiation = negotiationData;

      if (customerId) {
        filteredNegotiation = filteredNegotiation.filter(r => r.顧客ID === customerId);
      }
      if (startDate) {
        filteredNegotiation = filteredNegotiation.filter(r => new Date(r.交渉日) >= new Date(startDate));
      }
      if (endDate) {
        filteredNegotiation = filteredNegotiation.filter(r => new Date(r.交渉日) <= new Date(endDate));
      }

      renderNegotiationHistory(filteredNegotiation);
    }

    // 収益性指標を更新
    updateProfitabilityMetrics(customerData);

    // チャートを再描画
    drawMarketChart();
    drawTrendChart();
  });

  function updateProfitabilityMetrics(data) {
    if (!data || data.length === 0) return;

    const avgProfitRate = data.reduce((sum, r) => sum + (r.利益率 || 0), 0) / data.length;
    const avgMarketDiff = data.reduce((sum, r) => sum + (r.市場価格差異率 || 0), 0) / data.length;
    const avgNegotiationRate = data.reduce((sum, r) => sum + (r.価格交渉成功率 || 0), 0) / data.length;

    container.querySelector("#avg-profit-rate").textContent = `${avgProfitRate.toFixed(1)}%`;
    container.querySelector("#market-diff").textContent = `${avgMarketDiff > 0 ? '+' : ''}${avgMarketDiff.toFixed(1)}%`;
    container.querySelector("#negotiation-rate").textContent = `${avgNegotiationRate.toFixed(0)}%`;
  }

  // 初期データロード
  window.aivicApi.list(0).then(data => {
    if (data) renderNegotiationHistory(data);
  });

  window.aivicApi.list(5).then(data => {
    if (data) {
      renderCustomerPrices(data);
      updateProfitabilityMetrics(data);
    }
  });
}

