        <td>${r.交渉日 ? new Date(r.交渉日).toLocaleDateString() : ""}</td>
        <td>${r.商品ID || ""}</td>
        <td>¥${(r.提案単価 || 0).toLocaleString()}</td>
        <td>¥${(r.合意単価 || 0).toLocaleString()}</td>
        <td>
          <span style="background: ${getStatusColor(r.交渉ステータス)}; color: #fff; padding: 2px 6px; border-radius: 3px; font-size: 11px;">
            ${r.交渉ステータス || ""}
          </span>
        </td>
      </tr>
    `).join("");
