  // 色分け関数
  function getStrategyColor(strategy) {
    switch(strategy) {
      case 'プレミアム戦略': return '#8b5cf6';
      case '競争戦略': return '#f59e0b';
      case '浸透戦略': return '#10b981';
      default: return '#6b7280';
    }
  }

  function getRecommendColor(recommend) {
