    }
  }

  function getStatusColor(status) {
    switch(status) {
      case '合意': return '#22c55e';
      case '交渉中': return '#3b82f6';
      case '決裂': return '#ef4444';
      case '保留': return '#f59e0b';
      default: return '#6b7280';
    }
  }

  // チャート描画
  function drawImpactChart() {
    const canvas = container.querySelector("#impact-chart");
    const ctx = canvas.getContext("2d");

    // キャンバスサイズ設定
    canvas.width = 300;
    canvas.height = 180;

    ctx.clearRect(0, 0, 300, 180);

    // 背景
    ctx.fillStyle = '#f8fafc';
    ctx.fillRect(0, 0, 300, 180);

    // グリッド線
    ctx.strokeStyle = '#e2e8f0';
    ctx.lineWidth = 1;
    for(let i = 0; i <= 4; i++) {
      const y = 20 + (i * 35);
      ctx.beginPath();
      ctx.moveTo(40, y);
      ctx.lineTo(280, y);
      ctx.stroke();
    }

    // データ
    const months = ['1月', '2月', '3月', '4月', '5月', '6月'];
    const current = [100, 105, 98, 110, 115, 108];
    const predicted = [100, 108, 112, 125, 135, 142];

    // 現在の売上線
    ctx.strokeStyle = '#6b7280';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for(let i = 0; i < current.length; i++) {
      const x = 50 + (i * 40);
      const y = 160 - (current[i] - 80) * 2;
      if(i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 予測売上線
    ctx.strokeStyle = '#22c55e';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for(let i = 0; i < predicted.length; i++) {
      const x = 50 + (i * 40);
      const y = 160 - (predicted[i] - 80) * 2;
      if(i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 月ラベル
    ctx.fillStyle = '#64748b';
    ctx.font = '10px sans-serif';
    ctx.textAlign = 'center';
    for(let i = 0; i < months.length; i++) {
      const x = 50 + (i * 40);
      ctx.fillText(months[i], x, 175);
    }
  }

  // 初期データ読み込み
  Promise.all([
    window.aivicApi.list(PRICE_STRATEGY_TABLE),
    window.aivicApi.list(CUSTOMER_ANALYSIS_TABLE),
    window.aivicApi.list(NEGOTIATION_TABLE)
  ]).then(([strategies, customers, negotiations]) => {
    renderStrategyRows(strategies || []);
    renderSensitivityRows(customers || []);
    renderNegotiationRows(negotiations || []);
    drawImpactChart();
  });

  // 分析実行ボタン
  container.querySelector("#btn-analyze").addEventListener("click", async () => {
    const startDate = container.querySelector("#period-start").value;
    const endDate = container.querySelector("#period-end").value;
    const segment = container.querySelector("#customer-segment").value;
    const category = container.querySelector("#product-category").value;

    if (!startDate || !endDate) {
      alert("分析期間を選択してください");
      return;
    }

    // 分析実行（実際はバックエンドで処理）
    const strategies = await window.aivicApi.list(PRICE_STRATEGY_TABLE);
    const filtered = strategies.filter(s => {
      if (segment && !s.分析対象顧客ID?.includes(segment)) return false;
      if (category && !s.分析対象商品コード?.includes(category)) return false;
      return true;
    });

    renderStrategyRows(filtered);

    // KPI更新
    const avgImprovement = filtered.reduce((sum, s) => sum + ((s.推奨単価 - s.現在単価) / s.現在単価 * 100), 0) / filtered.length;
    container.querySelector("#kpi-revenue").textContent = `+${avgImprovement.toFixed(1)}%`;
  });

  // 戦略フィルター
  container.querySelector("#strategy-filter").addEventListener("change", async (e) => {
    const strategies = await window.aivicApi.list(PRICE_STRATEGY_TABLE);
    const filtered = e.target.value ? strategies.filter(s => s.戦略区分 === e.target.value) : strategies;
    renderStrategyRows(filtered);
  });

  // 発注データ登録ボタン
  container.querySelector("#btn-order-entry").addEventListener("click", () => {
    window.showScreen("scr-1780316116662");
  });

  // エクスポートボタン
  container.querySelector("#btn-export").addEventListener("click", async () => {
    const strategies = await window.aivicApi.list(PRICE_STRATEGY_TABLE);
    if (!strategies || strategies.length === 0) {
      alert("エクスポートするデータがありません");
      return;
    }

    const headers = ["商品コード", "現在単価", "推奨単価", "戦略区分", "実施推奨度", "利益率", "リスク評価"];
    const csvContent = "\uFEFF" + [
      headers.join(","),
      ...strategies.map(r => [
        r.分析対象商品コード || "",
        r.現在単価 || 0,
        r.推奨単価 || 0,
        r.戦略区分 || "",
        r.実施推奨度 || "",
        r.利益率 || 0,
        r.リスク評価 || ""
      ].join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "price_strategy_analysis.csv";
    link.click();
  });

  // スケジュール設定モーダル
  const modal = container.querySelector("#schedule-modal");

  container.addEventListener("click", (e) => {
    const scheduleBtn = e.target.closest(".schedule-btn");
    if (scheduleBtn) {
      const row = scheduleBtn.closest("tr");
      const productCode = row.cells[0].textContent;
      const recommendedPrice = row.cells[2].textContent.replace(/[¥,]/g, "");

      container.querySelector("#schedule-product").value = productCode;
      container.querySelector("#schedule-price").value = recommendedPrice;
      modal.style.display = "flex";
    }
  });

  container.querySelector("#btn-schedule-cancel").addEventListener("click", () => {
    modal.style.display = "none";
  });

  container.querySelector("#btn-schedule-save").addEventListener("click", async () => {
    const productCode = container.querySelector("#schedule-product").value;
    const scheduleDate = container.querySelector("#schedule-date").value;
    const newPrice = container.querySelector("#schedule-price").value;

    if (!scheduleDate || !newPrice) {
      alert("実施予定日と新単価を入力してください");
      return;
    }

    // スケジュール保存（実際の実装では専用テーブルに保存）
    alert(`${productCode}の価格改定スケジュールを設定しました\n実施日: ${scheduleDate}\n新単価: ¥${parseInt(newPrice).toLocaleString()}`);
    modal.style.display = "none";
  });

  // 期間の初期値設定
  const today = new Date();
  const threeMonthsAgo = new Date(today.getFullYear(), today.getMonth() - 3, today.getDate());
  container.querySelector("#period-start").value = threeMonthsAgo.toISOString().split('T')[0];
  container.querySelector("#period-end").value = today.toISOString().split('T')[0];
}
